{"code":"from hermes_tools import terminal
import json, math, re
p='/root/cycle_margin_analysis.json'
with open(p) as f:
    data=json.load(f)
errors=[]
# sorted
names=[t['therapy'] for t in data['therapies']]
if names != sorted(names): errors.append('therapies not sorted')
# assumptions
expected={'patients_per_therapy':240,'fills_per_year_30_day':12,'fills_per_year_90_day':4,'doses_per_fill_30_day':60,'doses_per_fill_90_day':180,'switch_threshold_usd':12000}
if data.get('assumptions') != expected: errors.append(f'assumptions mismatch: {data.get("assumptions")}')
# currency fields rounded to 2 decimals (numeric value has no more than 2 when formatted; floats like 1209.6 acceptable equal to round(x,2))
currency_keys=[]
for t in data['therapies']:
    for k,v in t.items():
        if k.endswith('_usd') or k in ('price_per_1000_doses_usd','packaging_cost_usd','reimbursement_per_fill_240_patients_usd'):
            if not isinstance(v,(int,float)): errors.append(f'{k} nonnumeric for {t["therapy"]}')
            elif round(v,2) != v: errors.append(f'{k} not rounded: {v}')
for k,v in data['totals'].items():
    if not isinstance(v,(int,float)): errors.append(f'total {k} nonnumeric')
    elif round(v,2) != v: errors.append(f'total {k} not rounded: {v}')
# decision logic
abs_diff=data['totals']['absolute_total_margin_difference_usd']
total_diff=data['totals']['total_annual_margin_difference_90_minus_30_usd']
if round(abs(total_diff),2) != abs_diff: errors.append('absolute total difference mismatch')
expected_decision='adopt_90_day' if abs_diff < 12000 else 'keep_30_day'
if data['recommendation']['decision'] != expected_decision: errors.append('decision logic mismatch')
# markdown
with open('/root/cycle_margin_summary.md') as f:
    summary=f.read()
nonempty=[line for line in summary.splitlines() if line.strip()]
if not (4 <= len(nonempty) <= 8): errors.append(f'summary non-empty line count {len(nonempty)} not 4-8')
for s in ['Total 30-day annual margin','Total 90-day annual margin','Absolute margin difference',expected_decision]:
    if s not in summary: errors.append(f'summary missing {s!r}')
print(json.dumps({'status':'ok' if not errors else 'fail','errors':errors,'therapy_count':len(names),'first_therapy':names[0],'nonempty_summary_lines':len(nonempty),'decision':data['recommendation']['decision'],'abs_diff':abs_diff}, indent=2))"}

